class Solution {
public:
    vector<int> prisonAfterNDays(vector<int>& cells, int n) {
        unordered_map<int, int> seen;
        auto to_mask = [](const vector<int>& c) {
            int m = 0;
            for (int x : c) m = (m << 1) | x;
            return m;
        };
        auto step = [](const vector<int>& c) {
            vector<int> next(8, 0);
            for (int i = 1; i < 7; ++i) {
                if (c[i - 1] == c[i + 1]) next[i] = 1;
            }
            return next;
        };
        while (n > 0) {
            int mask = to_mask(cells);
            if (seen.count(mask)) {
                int cycle = seen[mask] - n;
                n %= cycle;
                if (n == 0) break;
            }
            seen[mask] = n;
            if (n > 0) {
                n--;
                cells = step(cells);
            }
        }
        return cells;
    }
};

class Solution {
    public int[] prisonAfterNDays(int[] cells, int n) {
        Map<Integer, Integer> seen = new HashMap<>();
        while (n > 0) {
            int mask = 0;
            for (int x : cells) mask = (mask << 1) | x;
            if (seen.containsKey(mask)) {
                int cycle = seen.get(mask) - n;
                n %= cycle;
                if (n == 0) break;
            }
            seen.put(mask, n);
            if (n > 0) {
                n--;
                int[] next = new int[8];
                for (int i = 1; i < 7; i++) {
                    if (cells[i - 1] == cells[i + 1]) next[i] = 1;
                }
                cells = next;
            }
        }
        return cells;
    }
}

var prisonAfterNDays = function(cells, n) {
    const seen = new Map();
    while (n > 0) {
        const key = cells.join(',');
        if (seen.has(key)) {
            const cycle = seen.get(key) - n;
            n %= cycle;
            if (n === 0) break;
        }
        seen.set(key, n);
        if (n > 0) {
            n--;
            const next = new Array(8).fill(0);
            for (let i = 1; i < 7; i++) {
                if (cells[i - 1] === cells[i + 1]) next[i] = 1;
            }
            cells = next;
        }
    }
    return cells;
};
